window.ScripturaLexicons.BDAG_PART_0178 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-01\" data-source=\"BDAG\" data-search=\"ἱστορέω verbo visitar para conhecer; conhecer pessoalmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱστορέω</td><td>verbo</td><td>visitar para conhecer; conhecer pessoalmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-02\" data-source=\"BDAG\" data-search=\"ἱστορία, ας, ἡ substantivo feminino investigação; relato; narrativa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱστορία, ας, ἡ</td><td>substantivo feminino</td><td>investigação; relato; narrativa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-03\" data-source=\"BDAG\" data-search=\"ἱστός, οῦ, ὁ substantivo masculino mastro; objeto vertical BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱστός, οῦ, ὁ</td><td>substantivo masculino</td><td>mastro; objeto vertical</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-04\" data-source=\"BDAG\" data-search=\"ἰσχνόφωνος, ον adjetivo de voz fraca; com dificuldade na fala BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσχνόφωνος, ον</td><td>adjetivo</td><td>de voz fraca; com dificuldade na fala</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-05\" data-source=\"BDAG\" data-search=\"ἰσχυροποιέω verbo fortalecer; tornar forte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσχυροποιέω</td><td>verbo</td><td>fortalecer; tornar forte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-06\" data-source=\"BDAG\" data-search=\"ἰσχυροποίησις, εως, ἡ substantivo feminino fortalecimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσχυροποίησις, εως, ἡ</td><td>substantivo feminino</td><td>fortalecimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-07\" data-source=\"BDAG\" data-search=\"ἰσχυρός, ά, όν adjetivo forte; poderoso; intenso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσχυρός, ά, όν</td><td>adjetivo</td><td>forte; poderoso; intenso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-08\" data-source=\"BDAG\" data-search=\"ἰσχυρότης, ητος, ἡ substantivo feminino força interior; resistência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσχυρότης, ητος, ἡ</td><td>substantivo feminino</td><td>força interior; resistência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-09\" data-source=\"BDAG\" data-search=\"ἰσχυρόω verbo fortalecer; ser forte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσχυρόω</td><td>verbo</td><td>fortalecer; ser forte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-10\" data-source=\"BDAG\" data-search=\"ἰσχυρῶς advérbio firmemente; corajosamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσχυρῶς</td><td>advérbio</td><td>firmemente; corajosamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-11\" data-source=\"BDAG\" data-search=\"ἰσχύς, ύος, ἡ substantivo feminino força; poder; vigor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσχύς, ύος, ἡ</td><td>substantivo feminino</td><td>força; poder; vigor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-12\" data-source=\"BDAG\" data-search=\"ἰσχύω verbo ter força; poder; ser capaz; prevalecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰσχύω</td><td>verbo</td><td>ter força; poder; ser capaz; prevalecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-13\" data-source=\"BDAG\" data-search=\"ἴσως advérbio talvez; provavelmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἴσως</td><td>advérbio</td><td>talvez; provavelmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-14\" data-source=\"BDAG\" data-search=\"Ἰταλία, ας, ἡ topônimo feminino Itália BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰταλία, ας, ἡ</td><td>topônimo feminino</td><td>Itália</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-15\" data-source=\"BDAG\" data-search=\"Ἰταλικός, ή, όν adjetivo italiano; itálico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰταλικός, ή, όν</td><td>adjetivo</td><td>italiano; itálico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-16\" data-source=\"BDAG\" data-search=\"ἰταμός, ή, όν adjetivo arrojado; impetuoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰταμός, ή, όν</td><td>adjetivo</td><td>arrojado; impetuoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-17\" data-source=\"BDAG\" data-search=\"ἰτέα, ας, ἡ substantivo feminino salgueiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰτέα, ας, ἡ</td><td>substantivo feminino</td><td>salgueiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-18\" data-source=\"BDAG\" data-search=\"Ἰτουραῖος, αία, αῖον adjetivo; topônimo itureu; região da Itureia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰτουραῖος, αία, αῖον</td><td>adjetivo; topônimo</td><td>itureu; região da Itureia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-19\" data-source=\"BDAG\" data-search=\"ἰχθύδιον, ου, τό substantivo neutro peixinho; peixe BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰχθύδιον, ου, τό</td><td>substantivo neutro</td><td>peixinho; peixe</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0178-20\" data-source=\"BDAG\" data-search=\"ἰχθύς substantivo masculino peixe BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰχθύς</td><td>substantivo masculino</td><td>peixe</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0178-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱστορέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver o verbete seguinte) futuro <span class=\"greek\">ἱστορήσω</span> ; 1º aoristo <span class=\"greek\">ἱστόρησα</span> ; particípio perfeito, genitivo plural <span class=\"greek\">ἱστορηκότων</span> ( Ath. 30, 3); perfeito passivo, 3ª pessoa do singular <span class=\"greek\">ἱστόρηται</span> 1 Esdr 1:31 (Ésquilo, Heródoto e outros no sentido de «investigar» etc.; inscrições, papiros , 1 Esdr, Just ., Ath. ) visitar (com o propósito de conhecer alguém ou alguma coisa; Plut ., Thes. 30, 3, Pomp. 640 [40, 2], Lucull. 493 [2, 9], Mor. 516c; Epict . 2, 14, 28; 3, 7, 1; OGI 694; Sb 1004; PLond III, 854, 5 p. 206 [I a.d. ]; Jos. , Bell. 6, 81 , Ant. 1, 203, referindo-se a um monumento) <span class=\"greek\">ἱστορῆσαι</span> <span class=\"greek\">Κηφᾶν</span> conhecer pessoalmente Cefas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:18</a> (GKilpatrick, volume comemorativo de TManson , organizado por AHiggins ’59, 144–49 «obter informações de»; em oposição a ele OHofius, ZNW 75, ’84, 73–85 [referências]; mas ver JDunn, ibid. 76, ’85, 138f. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:23</a> variante de leitura [ Clem. Al. , Strom. 1, 19 p. 58, 20 St.]).— DELG sob o verbete <span class=\"greek\">οἶδα</span> . M-M . TW . Sv .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱστορία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver o verbete anterior; Hdt. +) originalmente «investigação»; depois, o resultado da investigação: «narrativa, relato, exposição»</p><p class=\"entry-text\">① relato, narrativa, em sentido geral <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ιβ</span>´ <span class=\"greek\">φυλῶν</span> nos «relatos das 12 tribos» GJs 1:1; <span class=\"greek\">γράψας</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">ταύτην</span> 25:1a; cf. <span class=\"greek\">γράψαι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἱ</span> . 25:1b. Referindo-se a um relato específico <span class=\"greek\">ἱστορίαν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">γυναικὸς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πολλαῖς</span> <span class=\"greek\">ἁμαρτίαις</span> <span class=\"greek\">διαβληθείσης</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, <span class=\"greek\">ἣν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">Ἑβραίους</span> <span class=\"greek\">εὐαγγέλιον</span> <span class=\"greek\">περιέχει</span> um relato, registrado no Evangelho dos Hebreus, acerca de uma mulher acusada de muitos pecados na presença do Senhor Papias ( 2:17 ).</p><p class=\"entry-text\">② narrativa como experiência pessoal, relato <span class=\"greek\">μήτι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">ἀνεκεφαλαιώθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἱ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀδάμ</span>; reproduziu-se em mim a história de Adão? ( cf. ApcMos 7) GJs 13:1.— DELG sob o verbete <span class=\"greek\">οἶδα</span> . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱστός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( Homero e outros ; pap , LXX ; TestSol 12:6 C; EpArist 320 [ provavelmente «rolos» de tecido]) literalmente «algo colocado na vertical» mastro, em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:38</a>, segundo conjectura de SNaber, Mnemosyne n.s. 23 1895, 267ff (mas ver Bruce, Acts, comentário à passagem ); ver também DELG e Frisk .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσχνόφωνος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( <span class=\"greek\">ἰσχνός</span> «fraco» + <span class=\"greek\">φωνή</span> (ver o verbete) ; Heródoto e outros ; Ex; Ezk. Trag. 114 [em Eus. , PE 9, 29, 9]) de voz fraca, mas também com dificuldade ou impedimento na fala 1 Cl 17:5 ( Ex 4:10 ).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσχυροποιέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( <span class=\"greek\">ἱσχυρός</span> + <span class=\"greek\">ποιέω</span> ) futuro <span class=\"greek\">ἰσχυροποιήσω</span> ; 1º aoristo <span class=\"greek\">ἰσχυροποίησα</span> ; imperativo presente passivo <span class=\"greek\">ἰσχυροποιοῦ</span> (Políbio e outros ; Ezk 27:27 Aq .) fortalecer Diod S 17, 65; Herm. Wr. 16, 12) <span class=\"greek\">τινά</span>, alguém Hv 1, 3, 2 ; 4, 1, 3 . <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> fortalecer alguém na fé Hm 12, 6, 1 . Voz passiva (Antig. Car. 175; Epict . 2, 18, 7; 4, 9, 15; Vett. Val. 333, 7; 347, 5 al. ) Hs 6, 3, 6 . <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαθόν</span> para praticar o bem v 3, 13, 2 . <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐντολαῖς</span> na observância dos mandamentos 5:5.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσχυροποίησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver o verbete anterior; Clem. Al. , Strom. 4, 12, 85; Aëtius 12, 21) fortalecimento Hv 3, 12, 3 .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσχυρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">ἰσχύς</span> e <span class=\"greek\">ἰσχύω</span> ; Ésquilo e outros) comparativo <span class=\"greek\">ἰσχυρότερος</span> ( Hdt. +; ins , pap , LXX ; Ar. 1, 2; Just ., D . 103, 3; Ath. 34, 2) em geral, «forte, poderoso, vigoroso».</p><p class=\"entry-text\">① relativo à força física, mental ou espiritual, dito de seres vivos: forte</p><p class=\"entry-text\">ⓐ dito de seres transcendentes: de Deus ( SIG 216, 1 [IV b.c. ] <span class=\"greek\">ἰσχυρῷ</span> <span class=\"greek\">θειῷ</span> [= <span class=\"greek\">θεῷ</span> ver nota 4] <span class=\"greek\">Σανέργει</span> ; Dt 10:17 ; 2 Macc 1:24 e frequentemente ; TestSol C 12, 3; Philo , Spec. Leg. 1, 307 ; PGM 10, 11; 12, 374; 36, 105; Just ., D . 103, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:8</a>. De anjos ( PGM 3, 71f <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">κραταιὸς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἰσχυρός</span> ) 5:2 ; 10:1 ; 18:21. De Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:22</a> ; cf. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:22</a> (ver abaixo sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:21</a> ). Daquele que viria depois de João Batista <span class=\"greek\">ἰσχυρότερός</span> <span class=\"greek\">μου</span> (cf. Judg 5:13 A; PGM 13, 202) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:11</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:7</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:16</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀσθενὲς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἰσχυρότερον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:25</a> (cf. Philo , Ebr. 186 <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀσθενές</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">ἰ</span> .). De Satanás, que pode ser o <span class=\"greek\">ἰσχυρός</span> da parábola <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:29</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:27</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:21</a> (cf. PGM 5, 147 o <span class=\"greek\">δαίμων</span>, que chama a si mesmo <span class=\"greek\">ἰσχυρός</span> , e o <span class=\"greek\">ἰσχυρός</span> de 13, 203, que, segundo 197, é <span class=\"greek\">ἔνοπλος</span> , bem como o <span class=\"greek\">Φόβος</span> <span class=\"greek\">καθωπλισμένος</span> de 528, lutando contra o <span class=\"greek\">ἰσχυρότερος</span> de 543; Mel. , P. 102, 783). Caso Satanás não seja o referente, essas passagens, juntamente com <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:22</a> (ver acima), pertencem à subdivisão b abaixo.</p><p class=\"entry-text\">ⓑ dito de seres humanos ( em oposição a <span class=\"greek\">ἀσθενής</span>, como em Fílon , Somn. 1, 155 ; Tat . 32, 2f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:10</a> ; Agr . 4.— 1J 2:14 ; Hs 9, 15, 1 . <span class=\"greek\">ἰ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πολέμῳ</span> poderosos na guerra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:34</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> Hv 3, 5, 5 ; m 11, 4 . <span class=\"greek\">οἱ</span> <span class=\"greek\">ἰσχυροί</span> ( Ps.-X ., Constitution of Athens 1, 14; 4 Km 24:15 codd. ; Da 8:24 Theod. ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:15</a> ; 19:18. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἰ</span> . 1 Cl 13:1 ( Jer 9:22 ); 38:2. Mesmo o neutro <span class=\"greek\">τὰ</span> <span class=\"greek\">ἰσχυρά</span> se refere a pessoas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:27</a>.</p><p class=\"entry-text\">② relativo a grau elevado de intensidade quanto à força ou à impressão produzida, dito de coisas: violento, intenso, estrondoso, poderoso etc. (cf. IAndrosIsis , Kyme 16 referindo-se à justiça) <span class=\"greek\">ἄνεμος</span> violento ( TestSol 6:1 D ; Dio Chrys . 60 e 61 [77 and 78], 7 <span class=\"greek\">χειμὼν</span> <span class=\"greek\">ἰ</span> .) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:30</a> variante de leitura ; <span class=\"greek\">βροντή</span> estrondosa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:6</a>. <span class=\"greek\">κραυγή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:7</a>. <span class=\"greek\">φόβος</span> Hm 7:4 (=o temor do Senhor é muito produtivo). <span class=\"greek\">πίστις</span> 9:7, 10. <span class=\"greek\">μετάνοια</span> Hs 7:6 . <span class=\"greek\">λίθος</span> sólido, poderoso ( Sir 6:21 ) B 6:2 . <span class=\"greek\">πέτρας</span> <span class=\"greek\">ἰ</span> . B 11:5 ( Is 33:16 ). <span class=\"greek\">λιμός</span> uma fome intensa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:14</a> (cf. Petosiris , Fgm. 6, ln. 49 <span class=\"greek\">λιμὸς</span> <span class=\"greek\">ἰ</span> .; Hdt. 1, 94; SIG 495, 59 [c. 230 b.c. ] <span class=\"greek\">σιτοδείας</span> <span class=\"greek\">γενομένης</span> <span class=\"greek\">ἰσχυρᾶς</span> ; Gen 41:31 ). <span class=\"greek\">πόλις</span> poderosa ( Is 26:1 variante de leitura ; TestJud 5:1 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:10</a> (cf. também <span class=\"greek\">τεῖχος</span> X. , Cyr. 7, 5, 7; 1 Macc 1:33 variante de leitura Kappler; <span class=\"greek\">πύργος</span> Judg 9:51 B ). <span class=\"greek\">φωνή</span> estrondosa ( Aesop . Fab. 420 P. <span class=\"greek\">ἰσχυρᾷ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">φωνῇ</span> ; Ex 19:19 ; Da 6:21 Theod. ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:2</a> ; <span class=\"greek\">παράκλησις</span> <span class=\"greek\">ἰ</span> . forte encorajamento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:18</a>. <span class=\"greek\">ἰσχυροτέρας</span> <span class=\"greek\">ἀποκαλύψεις</span> revelações mais significativas Hv 3, 10, 8 . <span class=\"greek\">ῥῆμα</span> poderoso 1, 3, 4. (com <span class=\"greek\">βέβαια</span> e <span class=\"greek\">τεθεμελιωμένα</span>) <span class=\"greek\">πάντα</span> <span class=\"greek\">ἰσχυρά</span> tudo está firme 3, 4, 3. <span class=\"greek\">θέσις</span> Hv 3, 13, 3 . (com <span class=\"greek\">βαρεῖαι</span>, como em TestJud 9:2 ) <span class=\"greek\">ἐπιστολαί</span> de peso e vigor (cf. X. , Cyr. 3, 3, 48; Wsd 6:8 ) cartas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:10</a>. Não empregado em João (ver MBoismard, Le chaiptre 21 de StJean: RB 54, ’47, 491).— B. 295. DELG sob o verbete <span class=\"greek\">ἰσχύς</span> . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσχυρότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver os verbetes anterior e seguinte; Dionys. Hal. 3, 65, 2 Jac. variante de leitura ; Philo , Leg. All. 3, 204 ) poder, força (interior) <span class=\"greek\">προσῆλθεν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἰ</span> . recebestes poder Hv 3, 12, 3 . Referindo-se a pedras: solidez, resistência (cf. Job 6:12 <span class=\"greek\">ἰσχὺς</span> <span class=\"greek\">λίθων</span> ) Hs 9, 8, 7 .— DELG sob o verbete <span class=\"greek\">ἰσχύς</span> .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσχυρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver os dois verbetes anteriores; 1º aoristo, 3ª pessoa do plural <span class=\"greek\">ἰσχύρωσαν</span> Is 41:7 ) fortalecer; voz passiva com sentido ativo <span class=\"greek\">ἰσχυροῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐταῖς</span> sê forte neles (nos mandamentos) Hm 5, 2, 8 .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσχυρῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio de <span class=\"greek\">ἰσχυρός</span> ( Heródoto e outros ; LXX ; JosAs ; Philo , Aet. M. 21 ; Jos. , Ant. 12, 368 , C. Ap. 1, 127 ; Just ., D . 63, 1) com vigor, de maneira firme e confiável (com <span class=\"greek\">ἀνδρείως</span> ) <span class=\"greek\">ἀναστρέφεσθαι</span> comportar-se com firmeza e coragem Hs 5, 6, 6 . <span class=\"greek\">ὑποφέρειν</span> suportar corajosamente 7:5. <span class=\"greek\">ἀνθεστηκέναι</span> m 12, 5, 4 . <span class=\"greek\">ἑστάναι</span> permanecer firme v 3, 13, 3 . <span class=\"greek\">ταπεινοφρονῆσαι</span> mostrar-se extremamente humilde Hs 7:4 (simplesmente «em grande medida»: Antig. Car. 35; Appian , Liby. 96, §454; Diog. L. 1, 75 <span class=\"greek\">ἰ</span>. <span class=\"greek\">ἐτίμησαν</span> ).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσχύς, ύος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">ἰσχυρός</span> e <span class=\"greek\">ἰσχύω</span> ; Hes .+; raro em épocas posteriores e em inscrições e papiros [ por exemplo PMich 156—II a.d. ], mas frequente na LXX ; pseudepígrafos ; Philo ; Jos. , C. Ap. 1, 19 al. ; Just ., Ath. , Iren. ) capacidade de agir eficazmente: força, poder, vigor 1 Cl 13:1 ( Jer 9:22 ); 39:2; B 6:3 ; 12:11 ( Is 45:1 ); Hv 3, 12, 2 ; <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἰ</span> . pela força <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:11</a>. <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὅλης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰ</span> . com toda a força <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:30</a>, 33 ( <span class=\"greek\">ψυχῆς</span> variante de leitura ); 1 Cl 33:8 ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:27</a> (ver Herm. Wr. 1, 30 <span class=\"greek\">ἐκ</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἰσχύος</span> <span class=\"greek\">ὅλης</span> ); <span class=\"greek\">ἰσχύειν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἰ</span> . Hs 9, 1, 2 . (Com <span class=\"greek\">δύναμις</span> , como em Dio Chrys . 14 [31], 11; 30 [47], 3; Appian , Bell. Civ. 4, 71 §302; PLond III, 1319, 5 p. 272 [544/45 a.d. ]; cf. Thu . 7, 66, 3; 2 Ch 26:13 ; Jos. , Ant. 11, 44 ) <span class=\"greek\">ἄγγελοι</span> <span class=\"greek\">ἰσχύϊ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δυνάμει</span> <span class=\"greek\">μείζονες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:11</a>. Empregado com <span class=\"greek\">δύναμις</span> e palavras semelhantes como atributos de Deus ( <span class=\"greek\">ἰ</span> . como atributo divino na tragédia e frequentemente na LXX ; cf. <span class=\"greek\">τοῦ</span> <span class=\"greek\">λόγου</span> <span class=\"greek\">ἰ</span> . Orig ., C. Cels. 1, 62, 71) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:12</a> ; 7:12. cf. também 1 Cl 60:1 ; Dg 9:6 . Referindo-se a Deus <span class=\"greek\">κράτος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰ</span> . (cf. Job 12:16 <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">κράτος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἰσχύς</span> .; En 1:4 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">δυνάμει</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰσχύος</span> <span class=\"greek\">αὐτοῦ</span> ; Philo , De Prov. in Eus. , PE 8, 14, 38; Ath. 24, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:19</a> ; 6:10 (para as passagens de Efésios, comparar os paralelos de Qumran assinalados por KKuhn, NTS 7, ’61, 335, por exemplo 1QH 4, 32 ; 18, 8 ; 1QS 11, 19f ); 1 Cl 27:5 . Referindo-se ao Senhor <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">αὐτοῦ</span> ( Is 2:10, 19, 21 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:9</a>. Referindo-se ao poder da oração IEph 5:2 (cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἰσχύι</span> <span class=\"greek\">λόγου</span> PsSol 17:36 ; Lucian , Hist. Conscr. 43 <span class=\"greek\">τῆς</span> <span class=\"greek\">ἑρμηνείας</span> <span class=\"greek\">ἰσχύς</span> ; Alex. Aphr., Fat. 16, II 2 p. 186, 23 sobre o poder da verdade; Phalaris , Ep. 70, 1). Referindo-se ao poder de gerar <span class=\"greek\">ἐκ</span> <span class=\"greek\">καρποῦ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰσχύος</span> AcPl Ox 1602 , 12f ( AcPl Ha 8, 14 <span class=\"greek\">ὀσφύος</span> )=BMM recto 17.— DELG . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰσχύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro <span class=\"greek\">ἰσχύσω</span> ; 1º aoristo <span class=\"greek\">ἴσχυσα</span> ; particípio perfeito, singular neutro <span class=\"greek\">ἰσχυκός</span> ( Da 4:20 Theod. ) (ver <span class=\"greek\">ἰσχύς</span> ; Pind .+ no sentido de «ser forte, prevalecer»)</p><p class=\"entry-text\">① possuir as próprias forças físicas, gozar de boa saúde <span class=\"greek\">οἱ</span> <span class=\"greek\">ἰσχύοντες</span> os que têm saúde ( Soph ., Tr. 234; X. , Cyr. 6, 1, 24, Mem. 2, 7, 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:12</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:17</a>.</p><p class=\"entry-text\">② possuir os recursos pessoais necessários para realizar algo; ter poder, ser capaz, poder</p><p class=\"entry-text\">ⓐ <span class=\"greek\">πολύ</span> ser capaz de realizar muito (cf. Diod S 1, 60, 2 <span class=\"greek\">πλέον</span> <span class=\"greek\">ἰ</span> .; 4, 23, 3; Appian , Bell. Civ. 2, 88 §371 <span class=\"greek\">τοσοῦτον</span> <span class=\"greek\">ἰ</span> .; Jos. , C. Ap. 1, 77 <span class=\"greek\">μεῖζον</span> <span class=\"greek\">ἰ</span> ., Ant. 15, 88 <span class=\"greek\">πλεῖστον</span> <span class=\"greek\">ἰ</span> .) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:16</a>. <span class=\"greek\">τί</span> <span class=\"greek\">ταπεινοφροσύνη</span> … <span class=\"greek\">ἰσχύει</span> quanta força tem a humildade 1 Cl 21:8 ; <span class=\"greek\">πάντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:13</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">οὐδέν</span> não servir para nada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:13</a>. <span class=\"greek\">ὅτε</span> … <span class=\"greek\">ἴσχυσας</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἰσχύι</span> <span class=\"greek\">σου</span>, <span class=\"greek\">ὥστε</span> <span class=\"greek\">δύνασθαι</span> Hs 9, 1, 2 .</p><p class=\"entry-text\">ⓑ seguido de infinitivo ( Diod S 1, 83, 8; Plut ., Pomp. 58, 6; PEleph 17, 23; POxy 396; 533, 16; 1345 <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἴσχυσα</span> <span class=\"greek\">ἐλθεῖν</span> <span class=\"greek\">σήμερον</span> ; LXX ; TestSol 22:8; JosAs 10:8; Philo , Leg. All. 3, 27 ; Jos. , Bell. 6, 367 , Ant. 2, 86 ; Just ., A I, 44, 12 al. ; Tat . 15, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:28</a> ; 26:40 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:4</a> ; 14:37 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:48</a> ; 8:43 ; 14:6, 29f ; 20:26 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:6</a> (única ocorrência em João; ver JBoismard); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:10</a> ; 15:10 ; 25:7 ; 27:16 ; 2 Cl 18:2 ; Hv 1, 3, 3 . ter força suficiente <span class=\"greek\">σκάπτειν</span> para cavar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:3</a> ; cf. Hv 3, 8, 8 . <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀκτίνας</span> … <span class=\"greek\">ἀντοφθαλμῆσαι</span> fixar os olhos nos raios (do sol) B 5:10 . Em uso absoluto, embora o infinitivo possa ser facilmente suprido pelo contexto (como em Sir 43:28 ) <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἴσχυσαν</span> (<span class=\"greek\">ἐκβαλεῖν</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:18</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἰσχύσουσιν</span> (<span class=\"greek\">εἰσελθεῖν</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:24</a>.</p><p class=\"entry-text\">③ ter domínio, exercer poder, ser poderoso ( Diod S 11, 23, 3; PPetr II, 18, 12; Just ., D . 90, 4) <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ηὔξανεν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἴσχυεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:20</a>. <span class=\"greek\">μέχρι</span> <span class=\"greek\">πότε</span> <span class=\"greek\">θάνατος</span> <span class=\"greek\">ἰσχύσει</span>; até quando a morte conservará seu poder? GEg 252, 50. <span class=\"greek\">ἰ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐταις</span> (<span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐντολαῖς</span> )= ser forte na observância dos mandamentos Hm 5, 2, 8 variante de leitura Vencer, prevalecer ( Thu . 3, 46, 3; Dio Chrys . 17 [34], 19; ParJer 1:6 <span class=\"greek\">ἴσχυσα</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἱερὰν</span> <span class=\"greek\">πόλιν</span> ) <span class=\"greek\">ὁ</span> <span class=\"greek\">δράκων</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἴσχυσεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:8</a>. <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span> sobre alguém, contra alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:16</a>. MPol 3:1 ; cf. 9:1 <span class=\"greek\">ἴσχυε</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνορίζου</span> ser forte e corajoso (na fé).</p><p class=\"entry-text\">④ ter significado, ser válido, estar em vigor, especialmente como termo técnico jurídico ( Diod S 2, 33, 1; Aelian , VH 2, 38 <span class=\"greek\">νόμον</span> <span class=\"greek\">ἰσχύειν</span> ; SIG 888, 59; 151 <span class=\"greek\">ἴσχυσεν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">προστάγματα</span> ; PTebt 286, 7 <span class=\"greek\">νομὴ</span> <span class=\"greek\">ἄδικος</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">εἰσχύει</span> ; Ath. 2, 2) referindo-se a um testamento <span class=\"greek\">μήποτε</span> <span class=\"greek\">ἰσχύει</span> <span class=\"greek\">ὅτε</span> <span class=\"greek\">ζῇ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">διαθέμενος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:17</a>. <span class=\"greek\">οὔτε</span> <span class=\"greek\">περιτομή</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἰσχύει</span>, <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἀκροβυστία</span> nem a circuncisão nem a incircuncisão têm valor algum <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:6</a>. — Ter o valor de ( IGR IV, 915a, 12 <span class=\"greek\">ἡ</span> <span class=\"greek\">δραχμὴ</span> <span class=\"greek\">ἰσχύει</span> <span class=\"greek\">ἀσσάρια</span> <span class=\"greek\">δέκα</span> ; Jos. , Ant. 14, 106 ) <span class=\"greek\">ὅλον</span> <span class=\"greek\">ἐνιαυτὸν</span> <span class=\"greek\">ἰσχύει</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> o dia equivale a um ano inteiro Hs 6, 4, 4 .— DELG sob o verbete <span class=\"greek\">ἰσχύς</span> . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἴσως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio de <span class=\"greek\">ἴσος</span> ( Alceu , Fgm. 89, 2 Diehl [=344, 2 L. -P.]=«provavelmente»; Safo , Fgm. 98, 11 [= 96, 11 L. -P.]=«igualmente»; Theognis ; ins , pap , LXX ; como demonstram Alceu e Safo, o emprego oscilava [ cf. o uso inglês] entre comparação [igual, semelhante] e probabilidade [verossímil, provável]), na literatura aqui considerada: talvez, provavelmente (autores áticos; também PAmh 135, 16; PTebt 424, 3; POxy 1681, 4 <span class=\"greek\">ἴσως</span> <span class=\"greek\">με</span> <span class=\"greek\">νομίζετε</span>, <span class=\"greek\">ἀδελφοί</span>, <span class=\"greek\">βάρβαρόν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">εἶναι</span> ; 4 Macc 7:17 ; Philo , Aet. M. 60 ; 134 ; Jos. , Bell. 4, 119 , Ant. 4, 11 ; Just ., Ath. ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:13</a> ; GJs 17:2.— M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰταλία, ας, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( Soph ., Ant. 1119; Hdt. 1, 24 al. ; SIG 1229, 2 <span class=\"greek\">πλεύσας</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἰταλίαν</span> ; Philo ; SibOr ; frequentemente em Josefo) sempre com o artigo ( B-D-F § 261, 6 ) Itália <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:2</a> ( Jos. , Ant. 16, 7 <span class=\"greek\">ἧκον</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> ’ <span class=\"greek\">Ιτ</span>. ); 27:1, 6 ; subscrição de Hb (sem artigo). <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἰταλίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:24</a> ; ver <span class=\"greek\">ἀπό</span>, sentido 3b.—Kl.-Pauly II, 1479–85 ( bibliografia ).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰταλικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( Pla . et al. ; SIG 726, 4 [97/96 b.c. ]; 746, 19; 1171, 10; Philo , Vi. Cont. 48; Jos. , Ant. 9, 85 ; 18, 44 ; empréstimo vocabular na literatura rabínica ) italiano, itálico <span class=\"greek\">σπεῖρα</span> <span class=\"greek\">Ἰ</span> . a coorte italiana ( Arrian , Alan. 13 editado por ARoos II 1928 p. 181, 6 <span class=\"greek\">ἡ</span> <span class=\"greek\">σπεῖρα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">Ἰλταλική</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:1</a>. —Bibliografia em <span class=\"greek\">ἑκατοντάρχης</span> .— M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰταμός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(desde Ésquilo, Fgm. 282; Aristoph .; Demosth . et al. ; Lucian ; Aelian ; Ael. Aristid. 31, 5 K.=11 p. 128 D .; Jer 6:23 ; 27:42 ) arrojado, impetuoso Hm 11:12 .— DELG sob o verbete <span class=\"greek\">εἶμι</span> .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰτέα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e outros ; Diod S 5, 41, 5; PTebt 703, 195 [III b.c. ]; LXX ; Jos. , Ant. 3, 245 ; Just ., D . 86, 5 <span class=\"greek\">ἰτέας</span> [em lugar de <span class=\"greek\">στελέχη</span> <span class=\"greek\">φοινίκων</span> Ex 15:27 ]) salgueiro Hs 8, 1, 1f ; 8, 2, 7 .— DELG .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰτουραῖος, αία, αῖον</h1><div class=\"entry-meta\"><span>adjetivo; topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(desde Eupólemo [II b.c. ] 723 Fgm. 2 Jac. [em Eus. , PE 9, 30, 3], predominantemente no plural do substantivo masculino <span class=\"greek\">Ἰτουραῖοι</span> [ Appian , Mithrid. 106 §499, Bell. Civ. 5, 7, §31; Arrian , Alans 1 e 18; Jos. , Ant. 13, 318 ]. Schürer 561–67) <span class=\"greek\">ἡ</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">χώρα</span>, Itureia, região situada ao longo das cadeias do Líbano e do Antilíbano, pertencente à tetrarquia de Filipe, cuja capital era Cálcis <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:1</a>. Ver Schürer, no lugar citado, para fontes e bibliografia — M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰχθύδιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver o verbete seguinte; Aristófanes e outros ; também em papiros ) diminutivo de <span class=\"greek\">ἰχθύς</span>: peixinho ( Aelian , NA 6, 24 p. 150, 11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:34</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:7</a>. Evidentemente sem valor diminutivo: peixe ( PFay 117, 7 [108 a.d. ]; PFlor 119, 7 [254 a.d. ]; Synes ., Ep. 4 p. 166a) B 10:5 (= <span class=\"greek\">ἰχθύς</span> 10:10).— DELG sob o verbete <span class=\"greek\">ἰχθῦς</span> . M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0178-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰχθύς</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( Herodian 2, 936 prefere <span class=\"greek\">ἰχθῦς</span> ; ver Schwyzer I 350; DELG e Frisk sob o verbete <span class=\"greek\">ἰχθῦς</span> ; B-D-F § 13 ; Mlt-H. 141f), <span class=\"greek\">ύος</span>, <span class=\"greek\">ὁ</span> (Homero e autores posteriores; inscrições, papiros , LXX ; En 7:5 ; 101:7 ; PsSol 5:9 ; TestSol ; também PVindob 18:38 sobrescrito ; Test12Patr ; JosAs 10:14; Philo , Joseph ., Just ., Ath. ) acusativo plural <span class=\"greek\">ἰχθύας</span> ( Epict . 4, 1, 30; Arrian , Anab. 5, 4, 3; PFay 113, 13 [100 a.d. ].—A forma acusativa <span class=\"greek\">ἰχθῦς</span> [ Athen . 7 p. 327b] não é atestada na literatura aqui considerada ) peixe, como alimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:10</a> ; 14:17, 19 ; 15:36 ; 17:27 (ver RMeyer, OLZ 40, ’37, 665–70; JDerrett, Law in the NT , ’70, 258–60); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:38</a>, 41, 43 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:6</a>, 9 ; 9:13, 16 ; 11:11 ; 24:42 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:6</a>, 8, 11 ( Jos. , Bell. 3, 508 os <span class=\"greek\">γένη</span> <span class=\"greek\">ἰχθύων</span> no lago de Genesaré.— TestZeb 6:6 pescarias extraordinárias de peixes provocadas por intervenção divina). A carne dos peixes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:39</a>. <span class=\"greek\">ἰχθύες</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θαλάσσης</span> B 6:12 ( Gen 1:26, 28 ); cf. versículo 18; 10:10. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">αὐτῶν</span> ( <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑδάτων</span> ) GJs 3:3. Peixes naturalmente desprovidos de escamas não podem ser comidos pelos judeus B 10:1 (ver Lev 11:9–12 ; Dt 14:9f ).— RAC VII 959–1097 ( bibliografia ); D’Arcy Thompson, A Glossary of Greek Fishes ’47. B. 184. M-M .</p></section></article>\n"};
